// ---------- 编辑器回写 ----------
fn title_edited(text){
    let d = doc_by_id(cur_doc)
    if d == nil { return }
    if d.title != text {
        d.title = text
        d.version += 1
        d.modified = now()
        save_docs()
    }
}

fn body_edited(text){
    if cur_doc == "" { return }
    let d = doc_by_id(cur_doc)
    if d == nil { return }
    if doc_body(d) == text { return }
    let paras = text.split(regex("\n\n", ""))
    if paras.len() == 0 { paras = [""] }
    let cleaned = []
    for p in paras {
        cleaned.push(p.replace(regex("^\n+", ""), "").replace(regex("\n+$", ""), ""))
    }
    d.paragraphs = cleaned
    d.version += 1
    d.modified = now()
    save_docs()
    if sel_para >= cleaned.len() { sel_para = cleaned.len() - 1 }
    ui.para_list.render()
}

fn open_task(id){
    let t = task_by_id(id)
    if t == nil { return }
    cur_task = id
    cur_doc = t.doc_id
    show_page("review")
}
fn open_task_line(doc_id, task_id){
    let t = task_by_id(task_id)
    if t == nil { return }
    // 与原生版一致：只有待审阅 / 准备中的任务可跳回审阅页
    if t.status == "ready" || t.status == "preparing" {
        cur_doc = doc_id
        cur_task = task_id
        show_page("review")
    }
}
fn back_library(){
    cur_doc = ""
    cur_task = ""
    show_page("library")
}

